const src = `'use strict';

function sub(a, b) { return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function cross(a, b) { return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]; }
function dot(a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }

// Unit cube centered at origin, 8 vertices, 12 triangles, CCW winding seen from outside.
function cubeGeometry(side) {
  var s = (side === undefined) ? 1 : side;
  var h = s / 2;
  var positions = [
    [-h,-h,-h], [ h,-h,-h], [ h, h,-h], [-h, h,-h],
    [-h,-h, h], [ h,-h, h], [ h, h, h], [-h, h, h]
  ];
  var indices = [
    [4,5,6], [4,6,7],   // +z
    [1,0,3], [1,3,2],   // -z
    [7,6,2], [7,2,3],   // +y
    [0,5,4], [0,1,5],   // -y
    [1,2,6], [1,6,5],   // +x
    [0,4,7], [0,7,3]    // -x
  ];
  return { positions: positions, indices: indices };
}

function geometryCenter(positions) {
  var c = [0, 0, 0];
  for (var i = 0; i < positions.length; i++) {
    for (var j = 0; j < 3; j++) c[j] += positions[i][j];
  }
  return [c[0] / positions.length, c[1] / positions.length, c[2] / positions.length];
}

function audit(geometry) {
  var positions = geometry.positions;
  var indices = geometry.indices;
  var c = geometry.center || geometryCenter(positions);
  var faces = 0;
  var inwardFaces = 0;
  for (var f = 0; f < indices.length; f++) {
    var tri = indices[f];
    var a = positions[tri[0]];
    var b = positions[tri[1]];
    var d = positions[tri[2]];
    var n = cross(sub(b, a), sub(d, a));
    var centroid = [
      (a[0] + b[0] + d[0]) / 3,
      (a[1] + b[1] + d[1]) / 3,
      (a[2] + b[2] + d[2]) / 3
    ];
    faces++;
    if (dot(n, sub(centroid, c)) <= 0) inwardFaces++;
  }
  return {
    faces: faces,
    inwardFaces: inwardFaces,
    facesOutwardRatio: faces ? (faces - inwardFaces) / faces : 0
  };
}

function main() {
  console.log(JSON.stringify(audit(cubeGeometry(1))));
}

if (require.main === module) main();

module.exports = { cubeGeometry: cubeGeometry, audit: audit, main: main };
`;

